#include <list>

int main() {
    std::list<int> L = {1, 2, 3, 5};

    // O(1) insertion at the front
    L.push_front(0);

    // Locate the position of '3' (O(N) search)
    auto it = L.begin();
    while (*it != 3) { 
        ++it; 
    }

    // O(1) insertion in the middle
    L.insert(it, 4); // L is now {0, 1, 2, 4, 3, 5}

    // O(1) deletion
    L.pop_back(); // L is now {0, 1, 2, 4, 3}
}
